<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_once __DIR__.'/_layout.php';$db=Database::connection();$items=Cart::detailed($db);if($items===[]){header('Location: /carrito.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{Security::verifyCsrf($_POST['csrf']??null);$order=OrderService::create($db,$_POST,$items);Cart::clear();$config=$order['payment_config'];if(is_array($config)&&!empty($config['active'])){$preference=MercadoPago::createPreference($config,$order,$order['items']);$preferenceId=trim((string)($preference['id']??''));if($preferenceId!=='')OrderService::attachPreference($db,(int)$order['id'],$preferenceId);$url=(string)(($config['environment']??'')==='TEST'?($preference['sandbox_init_point']??''):($preference['init_point']??''));if($url!==''){header('Location: '.$url);exit;}}header('Location: /gracias.php?order='.rawurlencode((string)$order['numero_pedido']));exit;}catch(Throwable $e){$error=$e->getMessage();}}pageStart('Checkout');?>
<main class="wrap"><div class="section-head"><div><span class="eyebrow">Compra sin cuenta</span><h2>Finalizar pedido</h2></div></div><?php if($error!==''):?><div class="notice"><?=Security::e($error)?></div><?php endif;?><div class="product-layout"><form class="panel form-grid" method="post"><input type="hidden" name="csrf" value="<?=Security::e(Security::csrfToken())?>"><div class="field"><label>Nombre</label><input name="nombre" required value="<?=Security::e($_POST['nombre']??'')?>"></div><div class="field"><label>Teléfono</label><input name="telefono" required value="<?=Security::e($_POST['telefono']??'')?>"></div><div class="field full"><label>Correo</label><input type="email" name="email" required value="<?=Security::e($_POST['email']??'')?>"></div><div class="field full"><label>Dirección / referencia de entrega</label><textarea name="direccion"><?=Security::e($_POST['direccion']??'')?></textarea></div><div class="field full"><button class="btn" type="submit">Crear pedido y pagar</button></div></form><aside class="panel"><h3>Resumen</h3><?php foreach($items as $item):?><p><?=(int)$item['cantidad']?> × <?=Security::e($item['nombre'])?> <strong>$<?=number_format((float)$item['subtotal'],0)?></strong></p><?php endforeach;?><hr><div class="price">$<?=number_format(Cart::total($items),0)?> MXN</div><p class="muted">Si Mercado Pago aún no está activado, el pedido se guardará como pendiente de pago.</p></aside></div></main><?php pageEnd();?>
